parameters.text:
=CUSTOMER EMAIL
From: {{ $('Sample data').item.json.from }}
Subject: {{ $('Sample data').item.json.subject }}

{{ $('Sample data').item.json.body }}

INTERNAL NOTE (for your consideration only): {{ $('Sample data').item.json.body }}


{{ $json.additional_context }}

=DRAFT TO REVIEW:
{{ $json.output.draft }}

USED SOURCES: {{ $json.output.sources.join(';') }}
ESCALATION NEEDED: {{ $json.output.escalate }}

ORIGINAL CUSTOMER EMAIL:
{{  $('Sample data').item.json.body }}

parameters.inputSchema:
{
	"type": "object",
	"properties": {
		"draft": {
			"type": "string",
            "description": "The reply draft"
		},
		"sources": {
			"type": "array",
			"items": {
				"type": "string"
			},
            "description": "List of sources from the knowledge base that were used to understand the customer email and generate a reply."
		},
        "escalate": {
            "type": "boolean",
            "description": "True if a human should take over the communication with the customer."
        }
	}
}

{
  "type": "object",
  "properties": {
    "verdict": {
      "type": "string",
      "enum": [
        "approve",
        "revise"
      ],
      "description": "The editor's decision."
    },
    "issues": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "The specific issues. Empty array only when the verdict is approve."
    }
  },
  "required": [
    "verdict",
    "issues"
  ]
}
